const ehUuidEscola = function ehUuidEscola(valor) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(valor ?? ""));
};
const conferirDonoNoBanco = function conferirDonoNoBanco(entrada, sim, nao, escolaEntrada) {
  const rpc = entrada?.contextoRpc;
  const temMensagem = sim.message_id.trim() !== "";
  if (rpc === undefined || rpc === null) {
    if (escolaEntrada && temMensagem) return { ...sim, enviar: false, motivo: "conferir_dono", consultar_rpc: true };
    return sim;
  }
  if (typeof rpc !== "object" || rpc.ok === undefined) return sim;
  if (rpc.ok !== true) {
    const motivo = String(rpc.motivo ?? "");
    return nao(motivo === "pausada" || motivo === "conversa_com_equipe" ? motivo : "contexto_rpc_recusou");
  }
  if (!ehUuidEscola(rpc.school_id) || String(rpc.school_id).toLowerCase() !== sim.school_id) return nao("escola_divergente");
  if (String(rpc.telefone ?? "").trim() !== sim.telefone) return nao("telefone_divergente");
  return sim;
};
const contextoConfiavel = function contextoConfiavel(ctx) {
  return Boolean(ctx && typeof ctx === "object"
    && ctx.ok === true
    && ctx.error === undefined
    && ehUuidEscola(ctx.school_id)
    && typeof ctx.modo_simulacao === "boolean"
    && Array.isArray(ctx.modo_teste_numeros));
};
const contextoRpcConfiavel = function contextoRpcConfiavel(rpc, escolaEntrada) {
  return Boolean(rpc && typeof rpc === "object"
    && rpc.ok === true
    && rpc.error === undefined
    && ehUuidEscola(rpc.school_id)
    && escolaEntrada
    && String(rpc.school_id).toLowerCase() === escolaEntrada
    && typeof rpc.modo_simulacao === "boolean"
    && Array.isArray(rpc.modo_teste_numeros)
    && /^\d{8,20}$/.test(String(rpc.telefone ?? "").trim()));
};
