const decidirPelaRpc = function decidirPelaRpc(entrada, base, nao, escolaEntrada) {
  const rpc = entrada?.contextoRpc;
  if (rpc === undefined || rpc === null) {
    const temMensagem = base.message_id.trim() !== "";
    return { ...nao("contexto_desconhecido"), consultar_rpc: Boolean(escolaEntrada) && temMensagem };
  }
  if (!escolaEntrada) return nao("contexto_desconhecido");
  if (rpc && typeof rpc === "object" && ehUuidEscola(rpc.school_id) && String(rpc.school_id).toLowerCase() !== escolaEntrada) {
    return nao("escola_divergente");
  }
  if (rpc && typeof rpc === "object" && rpc.ok === false && (rpc.motivo === "pausada" || rpc.motivo === "conversa_com_equipe")) {
    return nao(rpc.motivo);
  }
  if (!contextoRpcConfiavel(rpc, escolaEntrada)) return nao("contexto_rpc_vazio");
  const falhou = base.no_falhou;
  if (!nosQueAceitamContextoRpc().includes(falhou)) return nao("fora_do_atendimento");
  if (entrada?.respostaSaiu === true) return nao("resposta_ja_saiu");
  const portao = entrada?.portao;
  if (portao && typeof portao === "object" && String(portao.acao ?? "") !== "atender") return nao("portao_nao_atende");
  const tel = String(rpc.telefone).trim();
  const lista = rpc.modo_teste_numeros.map(String);
  if ((rpc.modo_simulacao || lista.length > 0) && !lista.includes(tel)) return nao("fora_da_lista");
  return { ...base, enviar: true, motivo: "ok", school_id: escolaEntrada, telefone: tel };
};
const textoDoErro = function textoDoErro(erro) {
  if (erro == null) return "";
  if (typeof erro === "string") return erro.slice(0, 300);
  if (typeof erro !== "object") return String(erro).slice(0, 300);
  const partes = [];
  for (const campo of ["httpCode", "message", "description"]) {
    const valor = erro[campo];
    if ((typeof valor === "string" || typeof valor === "number") && String(valor).trim()) partes.push(String(valor).trim());
  }
  return partes.join(" | ").slice(0, 300);
};
const eh401 = function eh401(erro) {
  const httpCode = erro && typeof erro === "object" ? String(erro.httpCode ?? erro.statusCode ?? "") : "";
  if (httpCode === "401") return true;
  return /\b401\b|authorization failed|jwt expired/i.test(textoDoErro(erro));
};
const telefoneConfiavel = function telefoneConfiavel(mensagem) {
